"""Create the requested checking plan as DOCX from audited archive metadata."""
from pathlib import Path
import json
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT=Path(__file__).resolve().parents[2]
WORK=ROOT/'Reports/StructTrainClassic/_work/LegacyInferencePlan-20261123/work'
OUT=ROOT/'Reports/StructTrainClassic/_work/plans'


def main():
    data=json.loads((WORK/'plan-data.json').read_text(encoding='utf-8'))
    OUT.mkdir(parents=True,exist_ok=True)
    doc=Document(); section=doc.sections[0]
    section.page_width=Inches(8.5); section.page_height=Inches(11)
    section.top_margin=section.bottom_margin=Inches(.7)
    section.left_margin=section.right_margin=Inches(.78)
    for name,size in [('Normal',11),('Title',21),('Heading 1',15),('Heading 2',12)]:
        style=doc.styles[name]; style.font.name='Arial';style.font.size=Pt(size);style.font.color.rgb=RGBColor(0,0,0)
        style.paragraph_format.space_after=Pt(7)
        style.paragraph_format.line_spacing=1.08
        style.element.get_or_add_rPr().rFonts.set(qn('w:eastAsia'),'Arial')
    doc.styles['Title'].font.bold=True
    for style in doc.styles:
        for border in list(style.element.findall('.//'+qn('w:pBdr'))):
            border.getparent().remove(border)
    footer=section.footer.paragraphs[0];footer.alignment=2
    run=footer.add_run(); field=OxmlElement('w:fldSimple');field.set(qn('w:instr'),'PAGE');run._r.addnext(field)
    footer.style.font.name='Arial';footer.style.font.size=Pt(9)
    doc.core_properties.title='План проверки архивных обученных моделей'
    doc.core_properties.author='Codex'
    def p(value='',bold=False):
        para=doc.add_paragraph();para.add_run(value).bold=bold;return para
    def h(value,level=1):return doc.add_heading(value,level)
    def page(title):h(title).paragraph_format.page_break_before=True
    def table(headers,rows,widths=None):
        t=doc.add_table(rows=1,cols=len(headers));t.autofit=False
        if widths:
            for c,w in zip(t.columns,widths):c.width=Inches(w)
        for c,v in zip(t.rows[0].cells,headers):c.text=str(v)
        repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
        for values in rows:
            for c,v in zip(t.add_row().cells,values):c.text=str(v)
        for i,row in enumerate(t.rows):
            prop=row._tr.get_or_add_trPr();prop.append(OxmlElement('w:cantSplit'))
            for cell in row.cells:
                for para in cell.paragraphs:
                    para.paragraph_format.space_after=Pt(3);para.paragraph_format.space_before=Pt(3)
                    para.paragraph_format.line_spacing=1.02
                    for r in para.runs:r.font.size=Pt(10.5);r.bold=i==0
        borders=OxmlElement('w:tblBorders')
        for side in ['top','bottom','insideH']:
            el=OxmlElement('w:'+side);el.set(qn('w:val'),'single');el.set(qn('w:sz'),'4');el.set(qn('w:color'),'B8C0C8');borders.append(el)
        t._tbl.tblPr.append(borders)
        p()
        return t

    doc.add_paragraph('План проверки архивных обученных моделей',style='Title')
    p('Структурное обучение на ветке autoPreset')
    p('23 ноября 2026 года')
    p('Проверка должна установить, сохраняются ли архивные обученные структуры после загрузки на autoPreset и воспроизводятся ли их реакции при отключённом обучении. Основной результат сравнения — длины дендритов, число синапсов, физические связи и существенные параметры нейрона. Графики потенциалов и показатели классификации уточняют характер различий.')
    h('Основа проверки')
    p('Приоритетный каталог — E:\\Science-Repo\\nmsdk-git\\Docs\\ClassicStructTrainExperiments\\Эксперименты. Используются сохранённые конфигурации, протоколы, таблицы и output_data. ВКР, её PDF и презентации служат дополнительными источниками рисунков и параметров. Внешние статьи и книги учитываются как теоретические источники.')
    table(['Что найдено','Как использовать'],[
        ('20 сохранённых компонентов','18 NNeuronTrainer и 2 NNeuronLearner. Сначала проверить их происхождение и пригодность состояния.'),
        ('9 согласованных обученных состояний','TrainingPattern и обученные d и s согласуются с сохранённым графом. Проверить первыми.'),
        ('246 структурных записей output_data','Восстановить известные состояния, сохраняя исходные номера строк и фаз.'),
        ('361 полная запись структуры','С учётом протоколов и опубликованных таблиц образуют 70 групп одинаковых пар d и s в пределах алгоритма. Это кандидаты для устранения дубликатов.'),
        ('22 уникальные диаграммы XLSX','Изучены вместе с растровыми графиками собственных документов. Для них задано 18 семейств сравнительных визуализаций.')],[1.9,5.0])
    p('Полные реестры моделей, источников, структур и рисунков вынесены в сопровождающую книгу GraphComparisonPlan.xlsx. Наличие структуры в реестре означает возможность подготовить состояние для инференса; оно не является результатом нового обучения.')

    page('Сохранённые модели и порядок их выбора')
    p('Модель идентифицируется по TrainingPattern, TrainingDendIndexes, TrainingSynapsisNum и фактическому графу. InputPattern задаёт текущий стимул и может отличаться от обучающего примера. Например, M001 хранит структуру NT для примера 45, хотя текущий InputPattern соответствует примеру 84.')
    trained=[m for m in data['models'] if m['training_metadata_matches_graph']]
    table(['Модель','Обучающий ID','Текущий вход','Состояние в проекте'],[
        (m['id'],m['saved_training_id'],m['candidate_dataset_id'],'Активен' if m['effective_active'] else 'Отключён предок') for m in trained],[.8,1.15,1.2,3.75])
    p('Все девять находятся в Autocreate2022.03.11 11_12_05. M008 и M018 относятся к одному обучающему примеру 132 и имеют одинаковые счётчики структуры. Объединять их прогоны можно после сверки полного физического описания и режима изолированного запуска.')
    p('Примеры 110 и 132 не подменяются примерами 111 и 134 из основной таблицы распознавания. Если для сохранённого состояния нет соответствующего исторического столбца ответов, его реакции фиксируются отдельно, а историческое совпадение остаётся неоценённым.')
    p('Восемь состояний находятся в неактивных классификаторах. Их проверка включает исходный проект с сохранением активности и отдельный запуск целого сохранённого поддерева компонента в активной оболочке. Результаты этих двух режимов имеют разные протоколы.')
    p('M009–M017 не содержат согласованного обученного описания. M019 и M020 из relearning_1 и relearning_2 содержат крайне малые некорректные значения InputPattern и не имеют обученных метаданных. Эти снимки используются как отдельные диагностические случаи. Завершённые состояния для сопоставления восстанавливаются из надёжных записей протоколов и output_data.')
    p('У 2_seria_NT отсутствуют Model_00.xml и Parameters_00.xml. Состояния NT для нужных исторических случаев необходимо сформировать по структурным таблицам и документированному профилю параметров.')

    page('Восстановление состояния по архивным данным')
    p('Сначала выбирается полное исходное сохранённое состояние, соответствующее конкретному историческому случаю. При его отсутствии строится замороженная модель по пяти длинам дендритов и пяти числам синапсов. Недостающие физические настройки берутся из согласованного архивного профиля того же алгоритма; каждое такое дополнение фиксируется в паспорте состояния.')
    h('Таблица сравнения NT и NL',2)
    p('Файл «Инофрмация о длинах дендритов и числе синапсов.xlsx» обязателен как источник. В нём заполнены векторы длин для 31 случая NT и 110 случаев NL. Полный числовой вектор синапсов имеется для одного случая NL. В четырёх строках NT записаны значения со скобками, например 35(28). Для каждой такой строки сохраняются два согласованных варианта вектора: внешние значения и значения в скобках. Произвольные комбинации отдельных чисел не создаются.')
    p('136 строк содержат длины, но не дают полного вектора синапсов. Для них ищется совпадающий случай в протоколах и приложениях ВКР. Когда достоверного дополнения нет, состояние остаётся неполным. Отсутствующие числа не заменяются единицами и не подбираются по качеству распознавания.')
    h('Дополнительные восстановимые состояния',2)
    p('Из output_data получены 246 записей: 92 и 91 в журналах переобучения, 20 для схемы 0/1, по 7 для 3/4 и предварительной 0/(1(2)+4), 14 для исправленной схемы на десяти примерах и 15 для полного Iris. Лишняя запись относительно последовательности из 91 входа, неполные хвосты и дополнительные поля заголовков требуют отдельной проверки соответствия.')
    p('Неоднозначность кода предварительной схемы не мешает проверке инференса её явно записанных структур. Неполная запись ответов также не препятствует восстановлению полного структурного заголовка. Сопоставлять реакции можно только на тех входах, порядок которых установлен.')
    p('Из таблицы 7 ВКР дополнительно восстанавливаются состояния для примеров 51 и 61 и их среднего. Для среднего заданы d = [12,16,11,12,1] и s = [22,27,21,22,1]. Приложение В содержит 14 структур для эпох 0–13. Номера файлов и исходная шкала 1–14 сохраняются наряду с канонической нумерацией.')
    h('Сборка замороженного состояния',2)
    p('Полностью собрать граф, установить числа сегментов и синапсов, восстановить связи и известные сопротивления. Затем инициализировать всё активное поддерево и отключить обучение. Для исходной сохранённой модели запрещена незаметная пересборка в начальную структуру. После загрузки и Reset проверяются физические сегменты, синапсы, связи и IsInit. Происхождение «сохранённая модель» и «реконструкция» остаётся явным.')

    page('Устранение дубликатов и фиксация протокола')
    p('361 полная запись сведена к 70 кандидатным группам по алгоритму и паре векторов d и s. Эти группы не являются окончательным числом экспериментов. Одинаковые счётчики могут соответствовать разным сопротивлениям, классам сегментов, порогам, активным связям и начальному динамическому состоянию.')
    p('Окончательный ключ прогона включает алгоритм, каноническое физическое описание, существенные параметры, правила сброса, набор и порядок входов, точность входных значений, частоту расчёта и окно наблюдения. Источники одного состояния образуют связь многие к одному с единственным прогоном. Во всех таблицах и рисунках сохраняются ссылки на каждый исходный случай.')
    p('Разные NT и NL, варианты в скобках, различающиеся пороги и разные протоколы не объединяются. В последовательном инференсе запуск на 30 входах и запуск на 150 входах имеют разную предысторию. Ответы подвыборки нельзя автоматически брать из полного прохода. Повторы для проверки детерминизма учитываются как повторы одного эксперимента.')
    table(['Параметр','Правило'],[
      ('Исполнение','Только Release. Бинарник и рабочий каталог запуска — Bin/Platform/Win. Новые скрипты — в Scripts основного репозитория.'),
      ('Подготовленные копии','Bin/Configs/StructTrainClassic/LegacyInference. Исходные конфиги и документы сохраняются без изменений.'),
      ('Частоты и пороги','Использовать значения конкретной конфигурации и документа. 2000 Гц и 1.5 Гц — исходный профиль предыдущего стенда, который необходимо сверить с источником.'),
      ('Окно входа','Вывести из исторического кода и дискретного шага. 1334 шага предыдущей проверки — проверяемое условие, а не универсальная константа.'),
      ('Порядок входов','150 примеров Iris либо исходные 30 или 10. Хранить точность нормализации и фактический порядок.'),
      ('Сброс','Основной режим — историческая непрерывная последовательность. Независимый Reset перед каждым примером — отдельный диагностический режим.'),
      ('Обучение','IsNeedToTrain выключен; экспериментальные режимы не должны менять структуру. DataFromFile для внешней подачи стимулов не требуется.')],[1.6,5.3])

    page('Последовательность проверок')
    tests=[
      ('T01 Инвентаризация и привязка','Для каждого состояния зафиксировать источник, SHA256, алгоритм, обучающий ID, текущий вход, версию параметров и исторические результаты. Разрешить несовпадения TrainingPattern и InputPattern по их смыслу, а не переименованием обучающего примера.'),
      ('T02 Проверка загрузки','Снять описание исходного графа из XML. Загрузить подготовленную копию, отключив обучение до первого шага. Сверить описание до загрузки, после загрузки и после Reset. Не допустить замены сохранённого нейрона свежим шаблоном.'),
      ('T03 Готовность физической модели','Проверить все входные сегменты, фактическое количество синапсов, генераторные связи, параметры каналов и IsInit активных компонент. Короткий запуск не должен создавать, удалять или деактивировать элементы.'),
      ('T04 Контрольные стимулы','Для девяти согласованных сохранённых состояний подать собственный обучающий пример и примеры других классов. Записать генераторные спайки, отдельные сомы, их сумму и LTZone. Выявить неправильный канал или порог до длинной серии.'),
      ('T05 Полный исторический инференс','Выполнить точную исходную последовательность на каждом уникальном состоянии и протоколе. Сохранить один ответ на вход, время спайка, максимумы сигналов и структуру до и после. Проверить объём 150, 30 или 10 и обработку конца последовательности.'),
      ('T06 Восстановленные состояния','Собрать недостающие структуры из реестра. Сначала подтвердить d и s и физические параметры, затем выполнить T03–T05. Сравнить реконструкцию с исходной сохранённой моделью на тех случаях, где обе доступны.'),
      ('T07 Повторяемость','Повторить полный проход из того же начального состояния. Третий повтор выполнить для выявленных различий и контрольных представителей каждого профиля. Отдельно проверить непрерывный и независимый режимы сброса.'),
      ('T08 Сохранение и загрузка','Сохранить полученное замороженное состояние в новую конфигурацию, загрузить её и повторить контрольные стимулы. Параметры, граф и реакции должны соответствовать выбранному протоколу.'),
      ('T09 Исторические рисунки','Построить семейства G01–G18 по приведённой далее спецификации. Графики обучения сопоставлять напрямую только при наличии соответствующих состояний итераций или при отдельном воспроизведении обучения.'),
      ('T10 Выпуск результатов','Создать DOCX с выводами и паспортами проверенных состояний, XLSX с числовыми рядами, редактируемыми графиками и отклонениями. Сохранить внутренние машинные журналы и манифесты источников.')]
    for title,body in tests:
        h(title,2);p(body)

    h('План воспроизведения исторических графиков')
    p('Просмотрены растровые иллюстрации собственных DOCX и презентаций, отдельные снимки и все 22 уникальные диаграммы из XLSX. В книге приведены точные источники и координаты диаграмм. Повторные копии ВКР, презентации, Итерации.xlsx и черновика связываются с одним эталоном.')
    for family in data['families'][:8]:
        h(f"{family['id']} {family['name']}",2)
        p(f"Источник: {family['sources']}. Оси: {family['axes']}. Ряды: {family['series']}.")
        p(family['comparison']+'.')
    h('Графики классификации и структурного соответствия')
    for family in data['families'][8:]:
        h(f"{family['id']} {family['name']}",2)
        p(f"Источник: {family['sources']}. Оси: {family['axes']}.")
        p(family['comparison']+'.')

    h('Правила количественного сравнения')
    h('Структура и параметры',2)
    p('Сравнивать известные целые d и s точно, поканально. Документированные альтернативы считать отдельными эталонными вариантами. Недостающие ячейки отмечать как неизвестные. Дополнительно сверять классы сегментов, синапсов и каналов, активность, сопротивления, пороги и связи. Совпадение счётчиков при различающихся связях не подтверждает соответствие модели.')
    h('Сигналы',2)
    p('Для суммарного потенциала использовать SomaNeuronAmplitude(0,0). В обеих реализациях это сумма потенциалов сом. Индексы i+1 соответствуют отдельным сомам. Одновременно записывать события входных генераторов и выход LTZone, чтобы исключить сравнение разных наблюдаемых величин.')
    p('Историческую и новую осциллограммы показывать рядом и в наложении при одинаковых единицах и пределах осей. Допускается один документированный временной сдвиг относительно входного события. Растяжение времени и масштабирование амплитуд для улучшения совпадения не применяются. Для рисунков без числового ряда оцифровать оси и кривую, сохранив исходное изображение, точки и погрешность оцифровки.')
    p('Сравнить число пиков, времена и амплитуды максимумов, взаимные задержки каналов, ширину импульса и форму. Допуски вывести из шага интегрирования, точности исходных чисел и разрешения рисунка. Побитовое равенство чисел с плавающей точкой не требуется.')
    h('Показатели классификации',2)
    p('Рассчитывать TP FP FN TN по установленному классу и популяции. Отдельно выводить precision, recall, accuracy и balanced accuracy. Историческое (TP%+TN%)/2 соответствует balanced accuracy. Различия ответов на отдельных входах остаются диагностикой и не заменяют структурный критерий.')
    p('В исторической диаграмме Q на 150 примерах представлены количества ошибок: начальное значение 28. Нормированный риск для этого состояния равен 28/150, а процент ошибок — 18.6667%. Эти шкалы выводятся отдельными графиками. Значения процентов из подвыборок на 10 и 30 примеров не смешиваются с полным Iris.')
